    #[test]
    fn status_reports_how_far_the_saved_credential_record_can_be_trusted() {
        let directory = temporary("credential-evidence-dir");
        let missing = directory.join("gone.pem");
        let (root, state) = state_with_credential("credential-evidence", &missing);
        let evidence = |state: &BridgeState| {
            let status = state.status().expect("status");
            (
                status["credentials"]["evidence"].clone(),
                status["delivery_alarm"]["credential_evidence"].clone(),
                status["delivery_alarm"]["credential_problems"].clone(),
            )
        };
        let none = evidence(&state);
        let files = state.credential_files();
        state
            .write_credential_record(&files, unix_millis())
            .expect("save a fresh record");
        let current = evidence(&state);
        let stale_at = unix_millis() - CREDENTIAL_RECORD_STALE_AFTER.as_millis() as u64 - 1_000;
        state
            .write_credential_record(&files, stale_at)
            .expect("save an old record");
        let stale = evidence(&state);
        state
            .write_credential_record(&files, unix_millis() + 3_600_000)
            .expect("save a record from the future");
        let future = evidence(&state);
        fs::write(root.join(CREDENTIAL_RECORD_FILE), b"not json").expect("corrupt the record");
        let unreadable = evidence(&state);
        fs::remove_dir_all(root).expect("cleanup");
        fs::remove_dir_all(directory).expect("cleanup");
        assert_eq!(none.0, "none");
        assert_eq!(none.2, serde_json::json!([]));
        assert_eq!(current.0, "current");
        assert_eq!(current.1, "current");
        assert_eq!(current.2[0]["problem"], "missing");
        // An old observation still shows what it saw, marked stale.
        assert_eq!(stale.0, "stale");
        assert_eq!(stale.2[0]["problem"], "missing");
        // A record observed later than now (a clock set back) is not trusted as current.
        assert_eq!(future.0, "untrusted");
        assert_eq!(future.1, "untrusted");
        // A corrupt record is unreadable evidence, not a clean bill.
        assert_eq!(unreadable.0, "unreadable");
        assert_eq!(unreadable.1, "unreadable");
    }

    #[test]
    fn a_pipe_at_the_credential_record_is_unreadable_evidence_without_blocking_status() {
        let directory = temporary("credential-record-pipe-dir");
        let (root, state) =
            state_with_credential("credential-record-pipe", &directory.join("gone.pem"));
        let record = root.join(CREDENTIAL_RECORD_FILE);
        let path = std::ffi::CString::new(record.as_os_str().as_encoded_bytes()).expect("path");
        // SAFETY: `path` is a valid NUL-terminated path; mkfifo only creates the node.
        assert_eq!(unsafe { libc::mkfifo(path.as_ptr(), 0o600) }, 0, "mkfifo");
        let (sender, receiver) = std::sync::mpsc::channel();
        let reader = state.clone();
        std::thread::spawn(move || {
            let status = reader.status().map(|status| {
                (
                    status["credentials"]["evidence"].clone(),
                    status["delivery_alarm"]["credential_evidence"].clone(),
                )
            });
            let _ = sender.send(status.map_err(|error| error.to_string()));
        });
        let answered = receiver.recv_timeout(Duration::from_secs(30));
        fs::remove_dir_all(root).expect("cleanup");
        fs::remove_dir_all(directory).expect("cleanup");
        let (evidence, alarm_evidence) = answered
            .expect("status returns instead of blocking on the pipe")
            .expect("status");
        assert_eq!(evidence, "unreadable");
        assert_eq!(alarm_evidence, "unreadable");
    }

    #[test]
    fn credential_evidence_judges_freshness_against_the_time_after_reading() {
        let record = |observed_at_millis| -> Result<Option<CredentialRecord>> {
            Ok(Some(CredentialRecord {
                schema: CREDENTIAL_RECORD_SCHEMA.to_owned(),
                observed_at_millis,
                files: Vec::new(),
            }))
        };
        let checked = 1_800_000_000_000;
        let stale_after = CREDENTIAL_RECORD_STALE_AFTER.as_millis() as u64;
        // A refresh saved just before the check, after an earlier clock sample, is current.
        assert_eq!(credential_evidence(&record(checked), checked), "current");
        assert_eq!(
            credential_evidence(&record(checked - stale_after), checked),
            "current"
        );
        assert_eq!(
            credential_evidence(&record(checked - stale_after - 1), checked),
            "stale"
        );
        assert_eq!(
            credential_evidence(&record(checked + 1), checked),
            "untrusted"
        );
        assert_eq!(credential_evidence(&Ok(None), checked), "none");
        assert_eq!(
            credential_evidence(&Err(ChatRuntimeError::invalid("corrupt")), checked),
            "unreadable"
        );
    }

    #[test]
    fn a_refusal_interrupted_before_its_file_is_removed_is_finished_without_asking_again() {
        let (root, state, keys) = saved_receipt_reactions("receipt-refusal-interrupted", 2);
        // The state a refusal of the first leaves when the process ends after counting it and
        // before removing its file.
        let interrupted = |key: &str| {
            let saved = saved_receipt_reaction(&root, key);
            write_document(
                &root.join(RECEIPT_REACTION_REFUSAL_FILE),
                &ReceiptReactionRefusal {
                    schema: RECEIPT_REACTION_REFUSAL_SCHEMA.to_owned(),
                    refused: 1,
                    oldest_refused_key: key.to_owned(),
                    newest_refused_at_millis: 1,
                    last_detail: "owner_ack_policy_mismatch".to_owned(),
                    finalizing: Some(RefusalInFlight {
                        key: key.to_owned(),
                        request_id: saved.request_id,
                    }),
                },
            )
            .expect("write the interrupted refusal");
        };
        let path = |key: &str| {
            root.join(RECEIPT_REACTION_DIRECTORY)
                .join(format!("{key}.json"))
        };
        interrupted(&keys[0]);
        drop(state);
        // Until it is finished, a read-only look counts it as refused and as failing.
        let marked = BridgeState::inspect(&root)
            .expect("inspect")
            .status()
            .expect("status")["receipt_reactions"]
            .clone();
        // Startup finishes it.
        let state = BridgeState::open(&root).expect("reopen");
        let gone_at_startup = !path(&keys[0]).exists();
        let mut transport = FinalRefusal {
            detail: "owner_ack_policy_mismatch".to_owned(),
            calls: 0,
        };
        let first_again = state
            .ensure_receipt_reaction(&keys[0], &mut transport)
            .expect("nothing waits");
        let after_startup = state.refused_receipt_reactions().expect("refused");
        // So does the next attempt at any reaction, without a restart.
        interrupted(&keys[1]);
        let second_again = state
            .ensure_receipt_reaction(&keys[1], &mut transport)
            .expect("nothing waits");
        let after_attempt = state.refused_receipt_reactions().expect("refused");
        let gone_after_attempt = !path(&keys[1]).exists();
        let record: ReceiptReactionRefusal =
            read_document(&root.join(RECEIPT_REACTION_REFUSAL_FILE), 64 * 1_024)
                .expect("refusal record");
        fs::remove_dir_all(root).expect("cleanup");
        assert_eq!(marked["waiting"], 2);
        assert_eq!(marked["failing"], 1);
        assert_eq!(marked["refused"], 1);
        assert!(gone_at_startup);
        assert!(first_again.is_none());
        assert_eq!(after_startup.count, 1);
        assert!(second_again.is_none());
        assert!(gone_after_attempt);
        assert_eq!(after_attempt.count, 1);
        assert_eq!(transport.calls, 0, "the helper is not asked again");
        assert!(record.finalizing.is_none());
    }

    #[test]
    fn a_print_reporter_passes_each_printed_prompt_to_its_runtime_and_to_its_caller() {
        #[derive(Default)]
        struct NotingRuntime {
            slept: std::cell::Cell<Duration>,
            noted: std::cell::RefCell<Vec<String>>,
        }

        impl agent::AgentRuntime for NotingRuntime {
            fn monotonic(&self) -> Duration {
                Duration::from_secs(7)
            }

            fn sleep(&self, duration: Duration) {
                self.slept.set(self.slept.get() + duration);
            }

            fn cancelled(&self) -> bool {
                true
            }

            fn delivery_wait_chunk(&self) -> Option<Duration> {
                Some(Duration::from_millis(3))
            }

            fn prompt_printed(&self, message_id: &str) {
                self.noted.borrow_mut().push(message_id.to_owned());
            }
        }

        let runtime = NotingRuntime::default();
        let reported = std::cell::RefCell::new(Vec::new());
        let printed = |id: &str| reported.borrow_mut().push(id.to_owned());
        let reporter = PrintReporter {
            runtime: &runtime,
            printed: &printed,
        };
        let reporter: &dyn agent::AgentRuntime = &reporter;
        assert_eq!(reporter.monotonic(), Duration::from_secs(7));
        reporter.sleep(Duration::from_millis(5));
        assert_eq!(runtime.slept.get(), Duration::from_millis(5));
        assert!(reporter.cancelled());
        assert_eq!(
            reporter.delivery_wait_chunk(),
            Some(Duration::from_millis(3))
        );
        reporter.prompt_printed("chat-one");
        assert_eq!(*runtime.noted.borrow(), ["chat-one"]);
        assert_eq!(*reported.borrow(), ["chat-one"]);
    }

    #[test]
    fn outbound_wire_binds_success_to_exact_uuid_action_and_authority() {
        let send = ReplySubmission {
            channel_id: "spaces/example",
            thread_id: "spaces/example/threads/one",
            body: "hello",
            request_id: "123e4567-e89b-42d3-a456-426614174000",
        };
        let encoded = encode_send_request(&send).expect("encode send");
        assert!(encoded.ends_with(b"\n"));
        let document: Value = serde_json::from_slice(&encoded).expect("request JSON");
        assert_eq!(
            document,
            serde_json::json!({
                "version": 1,
                "id": send.request_id,
                "action": "send",
                "channel_id": send.channel_id,
                "thread_id": send.thread_id,
                "text": send.body,
            })
        );
        let response = br#"{"version":1,"id":"123e4567-e89b-42d3-a456-426614174000","action":"send","ok":true,"receipt":{"message_id":"spaces/example/messages/reply"}}"#;
        assert_eq!(
            decode_send_response(response, &send).expect("decode send"),
            "spaces/example/messages/reply"
        );
        let outside = br#"{"version":1,"id":"123e4567-e89b-42d3-a456-426614174000","action":"send","ok":true,"receipt":{"message_id":"spaces/other/messages/reply"}}"#;
        assert_eq!(
            decode_send_response(outside, &send)
                .expect_err("outside authority")
                .outcome,
            OutboundOutcome::Unknown
        );

        let root = RootMessageSubmission {
            channel_id: "spaces/example",
            body: "new root",
            request_id: "123e4567-e89b-42d3-a456-426614174009",
        };
        let encoded = encode_root_message_request(&root).expect("encode root message");
        let document: Value = serde_json::from_slice(&encoded).expect("root request JSON");
        assert_eq!(
            document,
            serde_json::json!({
                "version": 1,
                "id": root.request_id,
                "action": "send",
                "channel_id": root.channel_id,
                "thread_id": null,
                "text": root.body,
            })
        );
        let root_response = br#"{"version":1,"id":"123e4567-e89b-42d3-a456-426614174009","action":"send","ok":true,"receipt":{"message_id":"spaces/example/messages/root"}}"#;
        assert_eq!(
            decode_root_message_response(root_response, &root).expect("decode root send"),
            "spaces/example/messages/root"
        );
        let outside_root = br#"{"version":1,"id":"123e4567-e89b-42d3-a456-426614174009","action":"send","ok":true,"receipt":{"message_id":"spaces/other/messages/root"}}"#;
        assert_eq!(
            decode_root_message_response(outside_root, &root)
                .expect_err("root receipt outside authority")
                .outcome,
            OutboundOutcome::Unknown
        );
        let multiline_root = br#"{"version":1,"id":"123e4567-e89b-42d3-a456-426614174009","action":"send","ok":true,"receipt":{"message_id":"spaces/example/messages/root\nforged"}}"#;
        assert_eq!(
            decode_root_message_response(multiline_root, &root)
                .expect_err("multiline root receipt")
                .outcome,
            OutboundOutcome::Unknown
        );

        let reaction = ReactionSubmission {
            channel_id: "spaces/example",
            message_id: "spaces/example/messages/source",
            emoji: "🤖",
            request_id: "123e4567-e89b-42d3-a456-426614174001",
        };
        let reaction_response = br#"{"version":1,"id":"123e4567-e89b-42d3-a456-426614174001","action":"ensure_reaction","ok":true,"receipt":{"reaction_id":"spaces/example/messages/source/reactions/robot","already_present":true}}"#;
        assert_eq!(
            decode_reaction_response(reaction_response, &reaction).expect("decode reaction"),
            ReactionReceipt {
                reaction_id: "spaces/example/messages/source/reactions/robot".to_owned(),
                already_present: true,
            }
        );
    }

    #[test]
    fn outbound_wire_preserves_provider_failure_evidence_and_rejects_unbound_frames() {
        let send = ReplySubmission {
            channel_id: "spaces/example",
            thread_id: "spaces/example/threads/one",
            body: "hello",
            request_id: "123e4567-e89b-42d3-a456-426614174000",
        };
        let failure = br#"{"version":1,"id":"123e4567-e89b-42d3-a456-426614174000","action":"send","ok":false,"error":{"code":"quota","detail":"try later","outcome":"not_applied","retryable":true}}"#;
        assert_eq!(
            decode_send_response(failure, &send).expect_err("provider failure"),
            OutboundFailure {
                code: "quota".to_owned(),
                detail: "try later".to_owned(),
                outcome: OutboundOutcome::NotApplied,
                retryable: true,
            }
        );
        let parser_failure = br#"{"version":1,"id":null,"action":null,"ok":false,"error":{"code":"invalid_json","detail":"bad input","outcome":"not_applied","retryable":false}}"#;
        assert_eq!(
            decode_send_response(parser_failure, &send)
                .expect_err("unbound parser failure")
                .outcome,
            OutboundOutcome::Unknown
        );
        let duplicate = br#"{"version":1,"id":"123e4567-e89b-42d3-a456-426614174000","action":"send","ok":true,"ok":false,"receipt":{"message_id":"spaces/example/messages/reply"}}"#;
        assert_eq!(
            decode_send_response(duplicate, &send)
                .expect_err("duplicate key")
                .outcome,
            OutboundOutcome::Unknown
        );
    }

